-- Rifts World Book 32: Lemuria - 10 skills, 21 Hydro-Psionics, 63 Biomancy and 8 Ocean Magic spells
-- 71 spells rows, 10 skills rows, 21 psionic_powers rows.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~173-lemuria-skills-psionics-spells.sql
--
-- Written by scripts/rows-sql.mjs from 3 worker file(s). Every value is
-- printable ASCII and every row cites its book. Rows are keyed on their
-- portable identity, never an id; a row already held is left as it is.

INSERT OR IGNORE INTO spells (name, level, ppe, ppe_note, variant_note, source, source_book, system, range, duration, damage, saving_throw, area_of_effect, casting_time, description, same_spell_as, tradition, ppe_permanent) VALUES
  ('Biomancy: Algae Bloom', 1, 4, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.87', 'rifts', '50 foot (15.2 m) bloom radius per level of experience, double along a ley line, quadruple at a ley line nexus; centered on the caster''s location', 'Takes 1D4 melee rounds to bloom; the multiplied algae is permanent and dissipates into the water over time', NULL, 'None', NULL, NULL, 'Multiplies algae that is already in the water into a thick cloud centered on the caster, who is affected too unless he swims clear. Anyone in the cloud cannot see and is -10 on every combat move (strike, parry, dodge and the rest) for as long as he stays in it. Movement and swimming are not slowed, but there is a 01-25% chance of clogging air hoses, vents and small light motors. Can also be cast simply to feed aquatic animals.', NULL, 'biomancy', NULL),
  ('Biomancy: Bio-Scan', 1, 4, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.87-88', 'rifts', 'Touch or up to 5 feet (1.5 m) away for a full scan, 20 feet (6.1 m) for monitoring vitals', 'Two melee rounds per level of experience; a complete scan takes 1D6 melee rounds. A Gene-Mage Biomancer can continuously monitor one specific patient for 30 minutes per level of experience', NULL, 'None for animals. Standard for sentient beings, but only if unwilling; automatic success on willing subjects. Mind Block or Alter Aura gives +3 to save. Unconscious or delirious subjects get no save; sleeping subjects are -2 to save. Does not work on supernatural beings or creatures of magic', NULL, NULL, 'Diagnostic scan of a person or animal that also links the caster to one subject so vital signs can be monitored. Shows heart rate, blood pressure, breathing and temperature; tissue, bone and organ injury and internal bleeding; foreign objects; disease, infection, parasites and symbiotes; drugs, poisons and chemical imbalance; cybernetic and bionic implants and damage to tissue around them; and the source of pain. Gene-Mages alone can also examine DNA for defects. It does not read minds, detect possession, heal, or work as a lie detector. Gives +30% to diagnose and +20% to treat disease and injury, but only to someone who knows biology and medicine.', NULL, 'biomancy', NULL),
  ('Biomancy: Bio-Scan: Plants', 1, 3, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.88', 'rifts', 'Touch or up to 5 feet (1.5 m) away for a scan, 30 feet (9.1 m) for monitoring vitals', 'Two melee rounds per level of experience; a complete scan takes 1D6 melee rounds. A Gene-Mage Biomancer can continuously monitor one specific patient for 30 minutes per level of experience', NULL, 'None for ordinary plants. Standard for sentient plant-beings, but only if unwilling; automatic success on willing subjects. Mind Block or Alter Aura gives +3 to save. Unconscious or delirious subjects get no save; sleeping subjects are -2 to save. Does not work on supernatural beings or creatures of magic such as a Millennium Tree or Memory Tree', NULL, NULL, 'The plant version of Bio-Scan, with a monitoring link to one plant. Shows hydration, CO2 use, photosynthesis, pollen and whether it is getting light, water and nutrients; any disease, infection, toxin, rot, mold or blight; parasites, insect infestation, nesting animals and symbiotes; physical trauma, burns, dehydration, root and cell damage and herbicide effects; the source of the damage; and DNA anomalies. On sentient plant beings it gives everything Bio-Scan does. It does not detect possession or heal; treatment needs a skill such as Botany or Gardening. Gives +30% to diagnose and +20% to treat disease and injury.', NULL, 'biomancy', NULL),
  ('Biomancy: Heal Plants', 1, 5, '5, 10 or 20 depending on the size of the plant; the most for trees', NULL, 'import', 'Rifts World Book 32: Lemuria p.88', 'rifts', 'One tree or 10 foot (3 m) area per level of experience', 'Permanent', NULL, 'None', NULL, NULL, 'Immediately mends a plant''s broken or damaged stem, branch or trunk, returning it to normal and raising its usual S.D.C. by 10%. The P.P.E. cost rises with the size of the plant, and trees cost the most.', NULL, 'biomancy', NULL),
  ('Biomancy: Ink Cloud', 1, 3, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.88-89', 'rifts', 'Self', '1D4 melee rounds +1 per level of experience (half in strong currents)', NULL, 'None', NULL, NULL, 'Like an octopus, the caster releases dark ink around himself, filling a 50x50x50 foot (15x15x15 m) volume; the area doubles at levels 5, 10 and 15. Anyone inside is blind (-10 to strike, parry, dodge, disarm, entangle and similar) and loses all sense of direction. Ocean Magic users can learn it at the same P.P.E. cost.', NULL, 'biomancy', NULL),
  ('Biomancy: Insect Signals', 1, 3, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.89', 'rifts', 'Self', '10 minutes per level of experience', NULL, 'None', NULL, NULL, 'The caster understands the sounds, scents and behaviour of any insect he can see or hear: whether it is agitated, afraid, hostile and likely to attack, content, hungry, hunting or foraging, mating, summoning others, laying a trail, or sounding a warning. When it is a warning, fear or hostility, he can also tell whether the threat concerns only the insects or the wider area.', NULL, 'biomancy', NULL),
  ('Biomancy: Whale Speak', 1, 4, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.89', 'rifts', 'One mile (1.6 km) per level of experience', '15 minutes per level of experience', NULL, 'None', NULL, NULL, 'Lets the caster talk with cetaceans (whales, dolphins, orcas). It is not telepathy: he must actually call out, in clicks and whistles at high frequency to dolphins and orcas, and in low-frequency song to most of the large whales, so other cetaceans and anyone with the Cetacean language skill can overhear. Ocean Magic users can learn it at the same P.P.E. cost.', NULL, 'biomancy', NULL),
  ('Biomancy: Amphibious', 2, 6, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.89', 'rifts', 'Self or one individual or animal per spell casting', '20 minutes per level of experience, triple duration along a ley line', NULL, 'None', NULL, NULL, 'Cast on a fish or other water-bound sea creature, it can breathe air and move on land at Speed 1D6+6 (doubled for an octopus or anything else with tentacles or legs). Cast on a land animal or humanoid, the fingers and toes web and the subject breathes and swims underwater to a maximum depth of one mile (1.6 km), with swimming Spd equal to the running Spd attribute. Ocean Magic users can learn it at the same P.P.E. cost.', NULL, 'biomancy', NULL),
  ('Biomancy: Bait Ball', 2, 6, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.90', 'rifts', '100 feet (30.5 m) per level of experience, line of sight, double along a ley line', 'Takes 1D4 melee rounds for the bait ball to form and lasts for two minutes (8 melee rounds) per level of experience', NULL, 'None', NULL, NULL, 'Packs one species of small fish (under two feet/0.6 m long) or plankton into a tight ball of 1D6x10 fish (1D4x1,000 if plankton), to lure, feed or distract a predator or to make the fish easy to net or pen. No effect on crustaceans, large fish, aquatic mammals or sentient beings. Chance of drawing the wanted predator: 84% if predators were seen nearby, 62% in waters that type is known to visit, 33% in unknown waters; 55% chance a different predator comes instead or as well. Ocean Magic users can learn it at the same P.P.E. cost.', NULL, 'biomancy', NULL),
  ('Biomancy: Bio-Electric Touch', 2, 4, '4 for the S.D.C. attack, 10 for the M.D. touch', NULL, 'import', 'Rifts World Book 32: Lemuria p.90', 'rifts', 'Touch only', 'Instant', '3D6 S.D.C. or 1D6 M.D. per touch', 'None', NULL, NULL, 'An electrical touch attack doing 3D6 S.D.C. for 4 P.P.E. or 1D6 M.D. for 10 P.P.E. Underwater the target takes full damage and everything else within a 5 foot (1.5 m) radius takes 1D4 S.D.C. (1 M.D. from the Mega-Damage version). It can restart a stopped heart: 01-25% for the untrained, 65% for a doctor, a Biomancer or someone directed by a character who knows biology or medicine. It also gives an S.D.C. battery another 1D6+4 minutes of life or jump-starts a weak car battery. Ocean Magic users can learn it at the same P.P.E. cost.', NULL, 'biomancy', NULL),
  ('Biomancy: Bioluminescence', 2, 7, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.90', 'rifts', '30 feet (9.1 m) per level of experience', '5 minutes per level of experience', NULL, 'Standard', NULL, NULL, 'Makes the caster''s body, or a target such as an opponent or the hull of a submersible, glow brightly to signal, lure prey or mark something. The glow hides the facial features of whoever carries it unless seen from within 15 feet (4.6 m), lights everything within 20 feet (6.1 m) well enough to read by, and is visible underwater for at least 650 feet (198 m) when unobstructed. Ocean Magic users can learn it at the same P.P.E. cost.', NULL, 'biomancy', NULL),
  ('Biomancy: Filter Feeder', 2, 10, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.90', 'rifts', 'Self or others by touch', '15 minutes per level of experience', NULL, 'None', NULL, NULL, 'The recipient can live on plankton as some whales and fish do, absorbing it magically while swimming about. A human or human-sized D-Bee is full after 1D6+8 minutes; a bigger creature needs 1D6+8 minutes for every 100 lbs (45 kg) of body mass. Ocean Magic users can learn it at the same P.P.E. cost.', NULL, 'biomancy', NULL),
  ('Biomancy: Harvest', 2, 5, '5 small plants, 8 medium-sized plants, 15 trees and plankton blooms; 30 to harvest from insects and simple animals; food paste 8 (one person per level) or 15 (two per level)', NULL, 'import', 'Rifts World Book 32: Lemuria p.90', 'rifts', 'Touch', '2D4 melees to perform, but the result is permanent', NULL, 'None', NULL, NULL, 'Coaxes a plant, without harming it, into yielding 1D4 pieces of fruit, nuts or vegetables (even out of season) or a fist-sized pouch of 1D4+5 ounces of seeds, sap, syrup, root, leaves, petals, pollen or an extract it naturally makes, poison included. For 30 P.P.E. an insect or simple animal such as a snake hands over 1D4 of its teeth or quills, or 1D4 doses of its poison or chemicals, without attacking. It can also turn inedible plants, seaweed, plankton and mashed insects into a nutritious paste: enough for one human-sized person per level for 8 P.P.E., or two per level for 15.', NULL, 'biomancy', NULL),
  ('Biomancy: Insect Chemical Trail', 2, 5, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.91', 'rifts', 'Self only', '10 minutes per level of experience. Scent lingers for 28 hours +2 hours per level of experience; half during or after rain, reduced by 90% in snow deeper than three inches (7.6 cm) or in a downpour', NULL, 'None', NULL, NULL, 'Everything the caster touches while the spell lasts, whether with bare skin, armor or clothing, is marked with an invisible insect scent. Only Biomancers using this spell, Insect Signals or Commune with Nature can detect, recognise and follow it (Base Skill 90%, halved in a downpour or in snow more than a couple of inches deep). Insects and insectoids such as the Xiticix can follow it as well; canines and other keen-nosed creatures cannot detect it at all.', NULL, 'biomancy', NULL),
  ('Biomancy: Plankton Bloom', 2, 8, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.91', 'rifts', '90 foot (27.4 m) radius per level of experience, double along a ley line, quadruple at a ley line nexus', 'Takes 1D6 melee rounds for the plankton to bloom; the multiplied plankton is permanent', NULL, 'None', NULL, NULL, 'Multiplies plankton already present into a light underwater haze. Anyone in the haze is -5 on every combat move (strike, parry, dodge and the rest) for as long as he stays in it. Movement is not slowed, but there is a 01-30% chance of clogging air hoses, vents and small light motors, and any technology, vehicle or weapon with a water intake has a 30% chance of failing until stripped and cleaned (a vehicle clears by running its engine at high speed for 2D4+1 melee rounds). It also feeds sea life, has a 01-33% chance of drawing whales, rays and other plankton eaters, and combines with Harvest to make food. Ocean Magic users pay twice the P.P.E.', NULL, 'biomancy', NULL),
  ('Biomancy: Animal Weaponry: Poison', 3, 10, '10; double (20) for the Mega-Damage lethal poison', NULL, 'import', 'Rifts World Book 32: Lemuria p.92', 'rifts', 'Self', 'One melee round per level of experience', 'Lethal poison: 2D6 direct to Hit Points (1D4 S.D.C. on a save). Mega-Damage lethal poison: 2D6 M.D. (1D4 M.D. on a save). In addition to the claw or bite damage', 'None for the caster; victims save vs poison: 16 or higher for paralysis of a limb and for fever, 14 or higher for lethal poison', NULL, NULL, 'An add-on cast after Animal Weaponry: Simple or Major, giving the claws and bite one poison chosen at casting. Paralyzing: a struck limb is numb for 1D4 melee rounds (arm unusable, skills with it -40%; leg halves speed, no kicks); save 16+ leaves only -1 on combat rolls and -5% skills; repeat hits add 1D4 rounds. Hits to head, neck or torso instead cost 5% Spd, -1 initiative and dodge and -5% skills each, cumulative; at 60% Spd lost, attacks and bonuses are halved. Lethal: save 14+ or take 2D6 to Hit Points (1D4 S.D.C. on a save); for double P.P.E. it does 2D6 M.D. (1D4 M.D. on a save). Fever: save 16+ or -25% skills, Spd -30%, -1 attack, -2 combat moves, -4 Perception, no initiative. A pulled punch cuts the claw or bite to one point or one die but not the poison.', NULL, 'biomancy', NULL),
  ('Biomancy: Coral Growth', 3, 8, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.92', 'rifts', '50 foot (15.2 m) radius of growth per level of experience', 'Permanent', NULL, 'None', NULL, NULL, 'Speeds the growth of coral to 100 times its natural rate in order to repair a damaged reef, enlarge or extend one, or start a new one. Living coral, or the organisms that build it, must already be there for the spell to work.', NULL, 'biomancy', NULL),
  ('Biomancy: Electrolocation', 3, 10, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.93', 'rifts', 'Self, with a sensing range of 100 feet (30.5 m) per level of experience', 'Two minutes per level of experience', NULL, 'Standard', NULL, NULL, 'The caster sees traces of bioelectricity that show where life forms and electrical energy (wiring and conduits included) are, even through total darkness, silty water, blizzards, magical illusions and other things that block sight. Positions are judged to within five feet (1.5 m), and the penalties for being blind are halved. Strong lines of electromagnetic energy and magnetic north can also be sensed. Ocean Magic users can learn it at the same P.P.E. cost.', NULL, 'biomancy', NULL),
  ('Biomancy: Fish Skin', 3, 10, '10 for S.D.C. armor, 35 for M.D.C. armor', NULL, 'import', 'Rifts World Book 32: Lemuria p.93', 'rifts', 'Touch', 'Permanent', NULL, 'Not applicable', NULL, NULL, 'Takes a layer of skin and scales from a big fish or two, or from a school of 1D4x10 small ones, and fuses it into a light, flexible, waterproof fabric and shaped around the caster or another person as a skintight suit. The suit keeps the wearer warm at depth and serves as armor with no movement penalties. For 10 P.P.E. it has A.R. 14 and 30 S.D.C. +5 per level of experience; for 35 P.P.E. it has 10 M.D.C. +5 per level. The suit is permanent and lasts until its S.D.C. or M.D.C. is gone. Works on fish-skinned monsters and sea serpents too.', NULL, 'biomancy', NULL),
  ('Biomancy: Insect Climb', 3, 8, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.93', 'rifts', 'Self or another person by touch', 'Two melee rounds (30 seconds) per level of experience', NULL, 'None', NULL, NULL, 'The recipient climbs like a bug over nearly any surface, walls and ceilings included. Base Skill is 98%, at -30% when moving faster than 75% of full running speed and -60% on glass, ice or other slick, smooth surfaces. Because it is so brief it is mostly used to reach a particular ledge or perch.', NULL, 'biomancy', NULL),
  ('Biomancy: Life Link', 3, 8, '8 to link to a specific animal or plant, 15 for an area; double the cost (and triple the duration) when the mage links himself to monitor and protect', NULL, 'import', 'Rifts World Book 32: Lemuria p.93-94', 'rifts', 'Self or other by touch. Once linked, the subject can travel up to 3,000 miles (4,800 km) away and stay in contact. An area link covers a 100 foot (30.5 m) radius', 'Five minutes per level of experience', NULL, 'Standard for animals and people', NULL, NULL, 'Ties a person to one animal, person, plant or a 100 foot (30.5 m) patch of nature so he feels its general emotions, not thoughts or sight; the caster can end it at will. Monitoring or relaxation: the linked person is -4 Perception, -2 initiative, half combat bonuses and -20% skills; linked to a healthy place he gains the benefits of meditation, and Lemurians and Biomancers are +10% to commune with nature. As a lesson, someone else is made to feel all the pain of the thing he is bound to, without injury: attacks and combat bonuses halved, no initiative or Perception Rolls, -50% skills. Optionally the G.M. has that target save vs Insanity (15 or higher) or roll percentile for a lasting change of attitude, from hatred of Biomancers to an obsessed crusader.', NULL, 'biomancy', NULL),
  ('Biomancy: Nutrient Bath', 3, 8, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.94', 'rifts', '12 feet (3.6 m) per level of experience', 'Roughly 2 minutes (8 melee rounds)', NULL, 'None', NULL, NULL, 'Surrounds the caster or one target with a bubble of vitamin-rich water that scrubs away grime (dirt, mud, algae, seaweed), parasites on the skin and skin disease, and heals burns, minor cuts, scrapes and abrasions. Wrinkles, acne and blemishes are cleared, giving +1 to P.B. for up to a month (only once per month). It also cleans and tends riding animals such as sea monsters, makes sick or rotten fish or squid safe to eat, and rids plants of rot and disease. Ocean Magic users pay twice the P.P.E.', NULL, 'biomancy', NULL),
  ('Biomancy: Repel Sharks', 3, 10, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.94', 'rifts', '10 foot (3 m) radius per level of experience around the spell caster', 'Five minutes per level of experience', '1D4 S.D.C.', 'Standard', NULL, NULL, 'Puts a low-level electrical field around the caster. Sharks, rays and other S.D.C. creatures that sense electricity tend to stay out of it; any that enter take 1D4 S.D.C. and must save vs Horror Factor 17 or flee 1D6x1000 yards/meters. Casters using Senses of the Shark and anyone in the shape of a shark or ray are affected the same way. It does nothing to M.D.C. sea monsters and sea serpents, to demons and other supernatural creatures, or to anything that cannot sense electricity. Ocean Magic users can learn it at the same P.P.E. cost.', NULL, 'biomancy', NULL),
  ('Biomancy: Seaweed Net', 3, 9, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.94', 'rifts', 'Net appears in the spell caster''s hands and can be thrown 20 feet (6.1 m)', 'One melee round per level of experience (half when removed from water or cast on dry land)', NULL, 'Dodge vs the attacker''s toss of the net; high roll wins', NULL, NULL, 'Forms a net from seaweed within a 100 foot (30.5 m) radius of the caster; with none that close, the spell fails. Making and throwing it takes two melee actions. It snares up to four human-sized victims or large animals within an 8 foot (2.4 m) radius, leaving each just one physical attack with no bonuses, usable only on someone within reach. Cuts repair instantly; only more than 18 M.D.C. dealt at one time, or Dispel Magic Barriers, destroys it, and the caster can cancel it at will. It can also be strung up as a light temporary barrier or pen.', NULL, 'biomancy', NULL),
  ('Biomancy: Tracking Barnacle', 3, 14, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.95', 'rifts', 'Self by touch or up to 30 feet (9.1 m) away; line of sight required', 'One hour per level of experience', NULL, 'None', NULL, NULL, 'Summons a mystic barnacle linked to the caster. It is stuck by hand onto a vessel, object or large creature, or cast onto one from up to 30 feet (9.1 m), where it holds fast and takes on its host''s color. The caster then senses its general direction, distance and location however far apart they are. It works best underwater and stops working 15 minutes after being taken out of the water.', NULL, 'biomancy', NULL),
  ('Biomancy: Weaponize Sea Anemone', 3, 12, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.95', 'rifts', 'Self or other by touch', '30 minutes per level of experience', '1D4 S.D.C. per anemone touched', 'None', NULL, NULL, 'Moves living sea anemones, up to two per level of experience, onto another underwater object or location: a door, doorknob, container, weapon, M.D. or S.D.C. armor, or the Biomancer''s own flesh. Bare skin that touches one takes 1D4 S.D.C. (Hit Point) damage; grappling, parrying or punching a covered opponent means stings from 1D4 anemones each time. Each anemone has 1D6+1 Hit Points and dies only to an attack aimed specifically at it. They are about the size of a tangerine and cannot grab an opponent or a weapon.', NULL, 'biomancy', NULL),
  ('Biomancy: Insect Silent Walking', 4, 10, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.95-96', 'rifts', 'Self only.', 'Five minutes per level of experience.', NULL, 'None', NULL, NULL, 'The caster moves without sound over noisy footing such as creaking boards, dead leaves, gravel or undergrowth, so long as he travels at no more than half his maximum Spd. Going faster cancels the effect and normal noise returns. Counts as Prowl at 70%; a caster who already knows Prowl uses it at 94% instead. The trail left is faint: anyone using Tracking to follow it is at -25%.', NULL, 'biomancy', NULL),
  ('Biomancy: Re-Hydrate', 4, 10, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.96', 'rifts', 'Touch or 20 feet (6.1 m) per level of experience; line of sight required.', 'Permanent.', NULL, 'None', NULL, NULL, 'Fully replaces lost water in one large plant, one human-sized creature, or 1D6+2 small animals (squirrel or lemur size and under). For people it ends thirst and also repairs the bodily harm of dehydration, including dried-out brain and body tissue. Any plant still alive, however withered, returns to full health. Plant targets per casting: one large tree, two medium trees, 1D4+2 saplings, a 10 foot (3 m) radius of plants, crops, flowers, bushes and shrubs, or twice that radius of grass.', NULL, 'biomancy', NULL),
  ('Biomancy: Safe Fire', 4, 7, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.96', 'rifts', 'Touch or up to 10 feet (3 m) away; line of sight required.', '30 minutes per level of experience.', NULL, 'None', NULL, NULL, 'Conjures a magical campfire good for cooking and for warming a small area. It never throws sparks or flares up, even in strong wind. When it ends it is immediately cold, leaving no embers or hot ash, so it cannot start a forest fire by accident.', NULL, 'biomancy', NULL),
  ('Biomancy: Scent Cloak', 4, 11, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.96', 'rifts', 'Self or others by touch.', '15 minutes per level of experience.', NULL, 'None', NULL, NULL, 'Removes all odor from the enchanted subject, on land or in water. While the spell lasts the subject gives off no scent at all, blends into the ordinary chemistry of the surrounding air or water, and cannot be tracked by smell. Tracking by sight or by other means still works.', NULL, 'biomancy', NULL),
  ('Biomancy: Seaweed Floating Platform', 4, 10, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.96', 'rifts', '6 foot (1.8 m) radius per level of experience.', '12 hours per level of experience.', NULL, 'None', NULL, NULL, 'Draws together seaweed from within a one mile (1.6 km) radius into a soft, spongy raft that floats half-submerged at the surface and holds one or several people, who can stand, walk or ride on it. Riders get wet and have no shelter from the weather, but will not sink or drown. Seaweed must already be in the area; none is created. Recasting may be needed to stop it breaking up, and the caster can end it at will. Also exists as an Ocean Magic spell at double the P.P.E.', NULL, 'biomancy', NULL),
  ('Biomancy: Weaponize Eel', 4, 16, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.96-97', 'rifts', 'Self or others by touch.', '15 minutes per level of experience.', 'Moray eel bite 1D6 S.D.C.; electric eel bite 1D4 S.D.C. plus 2D4 S.D.C. electric shock.', 'None', NULL, NULL, 'Like Weaponize Sea Anemone, but with a moray or other big, aggressive S.D.C. eel fixed to the subject''s armor or skin, usually forearm and shoulders. Each eel stays calm until combat, then acts on its own with two attacks per melee round, biting anyone in reach or anyone who grapples or strikes the wearer. Moray: 3D6 Hit Points/S.D.C., bite 1D6 S.D.C., +1 to strike and dodge. Electric eel: 3D6 Hit Points/S.D.C., bite 1D4 S.D.C., shock 2D4 S.D.C. with a 01-50% chance to stun fish and animals under one foot (0.3 m) long. The mage may release eels to attack a chosen foe for one melee round per caster level or until killed.', NULL, 'biomancy', NULL),
  ('Biomancy: Amplified Scent', 5, 21, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.97', 'rifts', '50 feet (15.2 m) per level of experience.', '10 minutes per level of experience.', NULL, 'Standard', NULL, NULL, 'Magnifies the natural odor of one person, animal or object. Anyone or anything trying to follow that target by scent, on land or underwater, gets +35%. The smell is obvious even to a weak nose and is equally strong in air and water; those nearby find it unpleasant and will tend to keep away and stay downwind.', NULL, 'biomancy', NULL),
  ('Biomancy: Animate Plants: Major', 5, 20, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.97-98', 'rifts', NULL, 'One minute per level of experience.', 'Vine whip 2D6 S.D.C.; underbrush, bushes and saplings (12 feet/3.6 m and smaller) 2D4 S.D.C.; medium adult trees (15-30 feet) 5D6 S.D.C., 1D6x10 S.D.C. or 1D4 M.D.; large adult trees (35-90 feet) 6D6 S.D.C., 2D4x10 S.D.C. or 2D4 M.D.; giant trees (over 100 feet tall or trunk over 10 feet thick) 2D4x10 S.D.C., 3D4 M.D. or 4D4 M.D., as the mage chooses.', 'None', '40 feet (12 m) plus 5 feet (1.5 m) per level of experience.', NULL, 'The caster mentally directs every plant in the area to entangle, conceal, give cover, or strike; trees stay rooted. Plant attacks per melee equal the caster''s own +2 (+1 more at levels 5, 10 and 15), each one using up a caster attack, and no other spell can be cast meanwhile. An attacking tree takes 5% of the damage it deals. Speed loss from entanglement (seaweed figure in brackets): short weeds/grass 15% (20%); tall weeds, light vines 30% (40%); thick vines 40% (60%) with 01-40% chance of being tied down after more than two melee rounds in one spot (combined P.S. 40 or Robotic/Supernatural P.S. 18 frees in two actions, otherwise 1D4+2 actions to cut loose); dense scrub and saplings 45% (65%); small to average trees 60% (70%); large trees or a seaweed clump 85%. Trees can weave branches into a barrier (two melee rounds to blast through 20 feet/6.1 m with M.D. weapons) and lift climbers 20-50 feet up; a fall does 3D6 S.D.C. with 01-75% chance of losing initiative and two melee attacks. Damage is not applicable to seaweed.', NULL, 'biomancy', NULL),
  ('Biomancy: Birth Giver', 5, 20, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.98', 'rifts', 'Self only.', 'As long as the birth takes.', NULL, 'None', NULL, NULL, 'Lets the caster act as a skilled attendant at the birth of any living animal, from hamster to horse to human or D-Bee, handling most procedures and emergencies such as a breech delivery. The ability ends when the young is born and leaves no lasting medical skill. The magic also calms the mother and lessens her pain; labor takes half the usual time and complications for mother or child, during or after, are rare.', NULL, 'biomancy', NULL),
  ('Biomancy: Insect Brother', 5, 11, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.98', 'rifts', 'Self or one or two others by touch.', 'Ten minutes per level of experience.', NULL, 'None', NULL, NULL, 'An aura and pheromones make insects and arachnids treat the subject as their own kind. They ignore him and will not bite or sting, so he can walk through a swarm or handle venomous species safely. A startled insect, or one that thinks it is being attacked, still strikes, and the spell gives no immunity to venom. It can also hide the scent of humans and D-Bees from Xiticix and other insect beings, but intelligent insectoids see through it the moment they have visual contact.', NULL, 'biomancy', NULL),
  ('Biomancy: Revitalize Plant Life', 5, 15, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.98', 'rifts', 'Touch or up to a casting distance of 50 feet (15.2 m) per level of experience; line of sight required.', 'The effects take 1D6 melee rounds to become apparent, but are permanent once the spell has been cast.', NULL, 'None', '25 foot (7.6 m) radius per level of experience.', NULL, 'Returns every plant in the area to normal health and hydration. Harm from drought, heat, flood, storms, frost, chemical or toxic exposure and trampling is reversed. It does not regrow or replace vegetation that is gone; only plants still present are restored.', NULL, 'biomancy', NULL),
  ('Biomancy: Seaweed Bloom', 5, 20, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.98-99', 'rifts', '60 foot (18.2 m) bloom radius per level of experience, double along a ley line, quadruple size at a ley line nexus. Cast at the magic user''s location.', 'It takes 1D4 melee rounds for the seaweed to bloom. The multiplied vegetation is permanent, dissipating into the water over time.', NULL, 'None', NULL, NULL, 'Multiplies seaweed already present into a dense mass that blocks light and passage; the caster is caught in it too unless he swims clear. Motorized vessels moving above 2 mph (3.2 km/1.7 knots) foul their engines and props and stop until cleared (2D6 minutes). Swimmers, animals and power armor can push through at 6 mph (9.6 km/5.2 knots). Visibility is 1D6+10 feet and Prowl or hiding gets +15%. Those inside are -5 Perception, -3 initiative, -4 to strike with ranged weapons, -35% Underwater Navigation and lose their sense of direction. Going faster than 6 mph doubles the penalties, top swimming speed is halved, and two melee attacks/actions are lost.', NULL, 'biomancy', NULL),
  ('Biomancy: Seaweed Lift', 5, 14, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.99', 'rifts', 'Self, with the range of movement for the platform being 10 feet (3 m) per level of experience.', 'One minute per level of experience, double at a ley line or within a ley line triangle like the Demon Sea/Bermuda Triangle.', NULL, 'None', 'Creates a four foot (1.2 m) diameter platform per level of experience; the caster can control the size.', NULL, 'Gathers seaweed from within one mile (1.6 km) into a platform atop a woven stalk that rises like an elevator, carrying people or cargo up into the air or through the water, and can shift sideways, forward or back within its movement range. Lifts at most two tons per caster level and moves at Spd 9. Enough seaweed must be present to reach the height wanted. Must be recast before it expires to keep it intact; the caster can cancel it. Only the caster moves it, and he must be on it or within 20 feet (6.1 m) of its base. Also an Ocean Magic spell at twice the P.P.E.', NULL, 'biomancy', NULL),
  ('Biomancy: Barnacle Armor', 6, 24, '24 for S.D.C. armor, 85 for M.D.C. armor', NULL, 'import', 'Rifts World Book 32: Lemuria p.99', 'rifts', 'Self or one person by touch.', 'Permanent.', 'Barnacle projectile volley: 5D6 S.D.C. (4 P.P.E.) or 2D6 M.D. (12 P.P.E.) per blast.', 'None', NULL, NULL, 'Forms a light, rock-hard shell of barnacles worn as body armor; it also keeps the wearer warm at depth, and comes off in pieces. Penalty -10% to skills such as Acrobatics, Climbing, Gymnastics, Prowl, Swimming and Tailing. For 24 P.P.E.: A.R. 18 and 48 S.D.C. +10 per caster level. For 85 P.P.E.: 24 M.D.C. +8 per level. It lasts until destroyed. On armor made for himself the mage can repair 40 S.D.C. or 16 M.D.C. per 24 P.P.E. (never above the starting total, and only while 25% or more remains), and can fire 1D4+4 barnacles for 4 P.P.E. (5D6 S.D.C.) or 12 P.P.E. (2D6 M.D.); range 20 feet (6.1 m) per level underwater, 40 feet (12.2 m) per level in air; each blast uses one melee attack.', NULL, 'biomancy', NULL);

INSERT OR IGNORE INTO spells (name, level, ppe, ppe_note, variant_note, source, source_book, system, range, duration, damage, saving_throw, area_of_effect, casting_time, description, same_spell_as, tradition, ppe_permanent) VALUES
  ('Biomancy: Coral Whispering', 6, 30, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.99', 'rifts', 'Self. The link is limited to a 300 foot (91.4 m) diameter per level of the spell caster.', 'Five minutes per level of experience.', NULL, 'None', NULL, NULL, 'The undersea counterpart of Tree Whispering. The caster communes with a nearby reef, or even scattered coral growths, in shallow tropical or cold deep water. He can put plain, basic questions to it or just sense its overall state and mood, using it for information and direction, for example who went by lately or what the seabed around and beneath it is like. Otherwise works as Tree Whispering (same spell level).', NULL, 'biomancy', NULL),
  ('Biomancy: Immune System Push', 6, 18, '18 for short illnesses such as flu or measles; 80 for chronic and life-threatening disease', NULL, 'import', 'Rifts World Book 32: Lemuria p.100', 'rifts', 'Self or others by touch.', 'Permanent.', NULL, 'None', NULL, NULL, 'Restores and strengthens the immune system so the body fights illness itself; it can cure AIDS, lupus, cancer and every immune deficiency. Against a cold, flu or other common disease the illness lasts half as long and its symptoms and penalties are halved. For serious chronic illness roll percentile: 01-33% disease slowed to a crawl, symptoms and penalties halved for 4D6+8 years (life extended at least that long), then it returns in full; 34-66% remission for 6D6+15 years, seemingly cured, then it returns in full; 67-00% completely cured, full health in 1D4 weeks. Usable only once in a given person''s lifetime.', NULL, 'biomancy', NULL),
  ('Biomancy: Nutrient Feed', 6, 15, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.100', 'rifts', 'Touch or an area.', 'The spell takes about 1D4 melee rounds to complete its work with permanent results.', NULL, 'None', '30 foot (9.1 m) radius per level of experience.', NULL, 'Delivers a whole day of food, nutrients and water to plants in less than a minute. It can feed one plant by touch, all vegetation, coral or kelp in the area, or just one chosen species while passing over weeds and unwanted growth. Edible, medicinal, fruit, vegetable or nut bearing plants fed this way daily for a month yield 50% more. The spell also draws beneficial insects and drives off harmful ones.', NULL, 'biomancy', NULL),
  ('Biomancy: Seaweed Path', 6, 24, '24, or 48 to double the path''s length and width', NULL, 'import', 'Rifts World Book 32: Lemuria p.100', 'rifts', 'The spell can be cast up to 50 feet (15.2 m) away per level of experience, double along a ley line or within a ley line triangle.', 'Two minutes per level of experience.', NULL, 'None', 'A length up to 120 feet (36.6 m) long and 15 feet (4.6 m) wide per level of experience, double along a ley line or within a ley line triangle; also double length and width when 48 P.P.E. are spent. The caster sets the direction.', NULL, 'Opens a clear lane through seaweed for fast travel. Underwater it is a tunnel as much as 15 feet (4.6 m) across; at the surface the cleared water is 15 feet (4.6 m) deep along the whole path. The 48 P.P.E. version is mostly used for ships and submarines. Outside the lane visibility is zero and the conditions and penalties of Seaweed Bloom apply to anyone who leaves it. Also an Ocean Magic spell at the same P.P.E.', NULL, 'biomancy', NULL),
  ('Biomancy: Tree Whispering', 6, 30, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.100-101', 'rifts', 'Self. The link is limited to a 300 foot (91.4 m) diameter per level of the spell caster.', 'Five minutes per level of experience.', NULL, 'None', NULL, NULL, 'Trees only, no other plants. The caster alone hears nearby trees as whispering voices and may listen generally or ask them things; trees treat a Biomancer as a friend and answer willingly. Replies are like Empathy and Telepathy together: repeated words and short phrases with flashes of image and sensation, not real conversation. Trees can point to water above or below ground, particular plants, herbs and edibles, minerals such as gold, silver or coal, what lies under their roots, soil quality, resident animals and their own health. Questions must be simple and specific and describe things by appearance; trees reckon time loosely (since sunrise, since the full moon) and count only as one, two, a few, many.', NULL, 'biomancy', NULL),
  ('Biomancy: Animate Plants: Superior', 7, 25, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.101', 'rifts', 'Affected area is 40 feet (12.2 m) per level of experience.', 'One minute per level of experience.', 'Same as Large Trees under Animate Plants: Major (6D6 S.D.C., 2D4x10 S.D.C. or 2D4 M.D.).', 'None', NULL, NULL, 'The caster takes over a single big tree, or a mass of seaweed, and works it like a puppet, giving it a rough humanoid form with a face, 2-4 arms and a pair of legs (possibly very short, or it walks on its roots instead). Unlike the lesser Animate Plants spells it can uproot and walk, and the caster can speak through it. Control takes all his concentration and every one of his melee attacks; the tree copies his movements. Tree S.D.C.: 3D6+12x100 (or one M.D.C. per 100 S.D.C.). Speed 5 +1 per caster level. Half damage from cold and pain, immune to possession and mind control, and +2 attacks per melee and +2 to strike on top of the caster''s own attacks and bonuses.', NULL, 'biomancy', NULL),
  ('Biomancy: Restore Bio-Armor', 7, 40, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.101', 'rifts', 'Touch or 15 feet (4.6 m); line of sight required.', 'Instant.', NULL, 'None', NULL, NULL, 'A Gene-Mage spell for maintaining Bio-Armor, the living power armor. Each casting does one of three things: restores 1D6x10 M.D.C. at once; repairs or regrows a single sensor or weapon system (antenna, fin, retractable blade and the like), which works immediately but has only one third of its normal M.D.C.; or refills one weapon system to a full payload. See the book''s Bio-Armor section.', NULL, 'biomancy', NULL),
  ('Biomancy: Seaweed Bridge', 7, 40, '40, or 240 to make the bridge last one hour per level of experience', NULL, 'import', 'Rifts World Book 32: Lemuria p.101', 'rifts', 'The spell can be cast up to 300 feet (91.5 m) away per level of experience.', 'Five minutes per level of experience.', NULL, 'None', 'Up to 300 feet (91.4 m) long and 10 feet (3 m) wide per level of experience.', NULL, 'Builds a long, sturdy span of seaweed that holds its place against wind, waves and current. At least one end must be anchored firmly, and it cannot serve as a life raft. It may lie underwater, float at the surface, or be fixed to land and hung in the air; in the air the extended hour-per-level duration is halved. It is wet and bouncy like a rope bridge yet carries vehicles and robots of 30 tons. The caster may cancel it at any time, with a visible unraveling that takes 1D4 melee rounds.', NULL, 'biomancy', NULL),
  ('Biomancy: Suspended Animation: Bio-Armor', 7, 40, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.101', 'rifts', 'Touch or 15 feet (4.6 m); line of sight required.', 'Hours to months; up to 30 days per level of experience.', NULL, 'None', NULL, NULL, 'Bio-Armor is a living symbiote that has to be worn 1D6+6 hours or more each week, or its bond with the host fails and the suit dies some hours afterward. A Gene-Mage uses this spell to put a suit into suspended animation for days to months, keeping it alive until the owner can take it back. It is also used to store one kind of Bio-Armor while the same warrior uses another. See the book''s Bio-Armor section.', NULL, 'biomancy', NULL),
  ('Biomancy: Tree Phasing', 7, 22, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.102', 'rifts', 'A specific direction desired by the spell caster.', 'Five minutes per level of experience.', NULL, 'None. Spell does not work on sentient plants.', 'A 100 foot (30.5 m) length per level of experience in whatever direction the Biomancer is looking. Width of the path is 15 feet (4.6 m) per level of experience.', NULL, 'Makes trees and vegetation (forest, jungle, living reef, seaweed) along a path intangible and semi-transparent so people and vehicles pass straight through. The caster must keep a hand on a tree where the path begins; he and that tree stay solid, and breaking contact, or knocking him out, makes everything solid again. Nothing can be trapped inside a re-solidified tree. After letting go he alone may keep walking through vegetation, provided he casts no other magic and uses no skill, and by touching another tree he can open a new stretch. Alternatively he moves through woods at full speed himself, or steps through a single touched tree. Rocks, animals, people and vehicles remain solid.', NULL, 'biomancy', NULL),
  ('Biomancy: Coral Menace', 8, 60, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.102-103', 'rifts', 'Immediate area.', '20 minutes per level of experience.', NULL, 'None', NULL, NULL, 'Animates a piece of coral about twice human size as a rock-like guardian that fights for, guards, scouts or lies in ambush for the caster, then re-attaches to the reef when the spell ends. Coral Menace: 300 M.D.C., 10-15 feet tall, I.Q. 7, P.S. 40 (Supernatural), P.P. 17, Spd 12 walking and 6 swimming, +3 strike and parry, +1 dodge, regenerates 2D6 M.D.C. per melee round. Four attacks per melee: punch or kick 4D6 M.D., power punch 1D4x10 M.D. (two attacks), or bio-energy bolt 3D6 M.D. (double to undead) at 100 feet. Obeys only its summoner, literally. Limits: one Menace at a time, and the caster may cast only one other spell per melee round while it exists. Carelessly getting it killed carries a cumulative 15% chance of losing all Biomancy powers until redeemed.', NULL, 'biomancy', NULL),
  ('Biomancy: Remove Parasites', 8, 50, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.103', 'rifts', 'Touch.', 'Results are permanent; takes 1D6+1 minutes to remove parasites.', NULL, 'None', NULL, NULL, 'Finds and drives out parasites from a host with no harm to host or parasite. Harm already done by the parasite is not healed, and any powers or benefits it gave leave with it. The caster must watch and coax the parasites out for the full 1D6+1 minutes; if the spell is interrupted or cancelled early they burrow back in. Has no effect on symbiotes.', NULL, 'biomancy', NULL),
  ('Biomancy: Bio-Energy Weapon', 9, 60, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.104', 'rifts', 'Self, i.e. a weapon held and used by the spell caster.', 'One melee round per level of experience.', '1D6 M.D. per level of experience (+10 M.D. vs supernatural evil, double damage vs undead)', 'None', NULL, NULL, 'Charges a weapon of organic material (wood, coral, bone; staff, spear, club or wooden/tooth/coral blade) held by the caster. Harm: 1D6 M.D. per caster level, +10 M.D. against supernatural evil, double against undead; half damage to inorganic targets (metal or plastic armor, robots, vehicles, cyborgs, force fields), full damage to living or organic armor. Against S.D.C. foes it does 1D6 S.D.C. per level, and only 1D6 S.D.C. unless the caster truly intends harm. Heal: laid on a wound it negates poison, expels bullets and fragments and closes the wound, restoring 2D6 Hit Points/S.D.C. or 1D6 M.D.C. per touch, one touch per melee round; 01-70% chance to wake an unconscious or comatose person, who also gets +20% to save vs Coma/Death.', NULL, 'biomancy', NULL),
  ('Biomancy: Creature of the Forest', 9, 70, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.104', 'rifts', 'Self.', '10 minutes per level of experience.', NULL, 'None', NULL, NULL, 'Hybrid metamorphosis into a furred lemur- or monkey-like humanoid one third normal size with a tail half body length. Moves through branches at full running speed, leaps 10 feet high and 15 feet across (+50% with a running start), Nightvision 300 feet, Acrobatics, Climbing, Rappelling and Tailing at 82% +1% per level, Prowl 58% +1% per level, +10 running Spd, +2 Perception from an elevated position, +1 initiative, +4 automatic dodge, +5 roll with impact/fall, and 01-50% chance to land unhurt from falls up to 100 feet. Keeps memories, skills and psionics; arboreal animals accept him. Limits: cannot cast spells or speak beyond single words and short phrases, and is too small for weapons or tools, though buttons, switches and keyboards can be worked.', NULL, 'biomancy', NULL),
  ('Biomancy: Reconfigure Bio-Armor', 9, 100, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.104', 'rifts', 'Touch.', 'A ritual that takes 15 minutes.', NULL, 'None', NULL, NULL, 'A 15 minute ritual that cuts a suit of Lemurian Bio-Armor''s symbiotic link to its old owner and re-keys it to the DNA and exact specifications of a new one, so armor from a retiring or re-equipping owner does not waste away and die. Reconfigured armor performs as good as new. The same ritual can restore a broken link between a neglectful existing owner and Bio-Armor that has disconnected and is about to die. See the book''s Bio-Armor section for the link rules.', NULL, 'biomancy', NULL),
  ('Biomancy: Bio-Field', 10, 100, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.105', 'rifts', 'Self.', 'One minute per level of experience.', NULL, 'None', NULL, NULL, 'The caster radiates life energy (plants briefly bloom where he steps). While active his Hit Points become M.D.C. (in S.D.C. settings, triple Hit Points instead) and he regenerates 6D6 M.D.C./Hit Points/S.D.C. once per melee round. The regeneration also applies to any living Bio-Armor or symbiotes he wears and to a riding animal or animal companion he is mounted on or that stays at his side. He is also +50% to save vs Coma/Death, +5 to save vs possession, and immune to disease and poison.', NULL, 'biomancy', NULL),
  ('Biomancy: Creature of the Sea', 10, 100, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.105', 'rifts', 'Self.', '10 minutes per level of experience.', NULL, 'None', NULL, NULL, 'Hybrid metamorphosis into a whale-like humanoid three times normal size with a whale or dolphin tail. Breathes water only (no air until he changes back), P.S. becomes Supernatural, +2D6+20 swimming speed, depth tolerance 8 miles (12.8 km), Hit Points plus S.D.C. become M.D.C. with 2D6 M.D.C. regenerated per melee round, bite 3D6 M.D., punches and tail swipes by Supernatural P.S., Nightvision 1,000 feet. Sea mammals and fish accept him. Limits: no spell casting, speech limited to single words and short phrases, too large for most human weapons and tools, webbed fingers cannot work buttons, switches or machines, and he survives only 1D4 melee rounds on dry land unless he changes back.', NULL, 'biomancy', NULL),
  ('Biomancy: Reverse Undead', 10, 100, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.105', 'rifts', 'Touch.', 'Instant.', NULL, '18+, Standard.', NULL, NULL, 'Breaks a vampire''s hold over a living victim, whether that hold is the Killing Bite or mind control by the undead, and returns the victim to normal and full health, so the process of turning that person must start over. A newly made vampire that has not yet fed on a living humanoid is restored to life on a roll of 01-75%; on success roll on both side-effect tables under Touch of Life, on failure it stays a vampire. Also negates Necromancy, turning animated dead and animated body parts back into inert remains.', NULL, 'biomancy', NULL),
  ('Biomancy: Nutrient Push: Soil', 11, 180, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.105', 'rifts', '500 foot (152 m) radius per level of experience.', 'Permanent.', NULL, 'None', NULL, NULL, 'With hands set in the earth or sea floor, the caster floods the ground with nutrients and bio-energy. Crop seeds and young plants reach harvest readiness in 1D6 minutes, tree seeds become saplings, saplings become small trees, and a mature tree, a coral reef or a kelp frond grows a further 25% and are at peak health. The soil stays rich for one year per caster level, and plants grown in it are 50% larger and yield 50% more for 2D6 years.', NULL, 'biomancy', NULL),
  ('Biomancy: Remove Symbiotes', 11, 150, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.105', 'rifts', 'Self only.', 'Permanent results, takes one hour to remove a symbiote.', NULL, '-2 if the removal is wanted, because the symbiotic organism resists the magic. +5 to save if the removal is unwanted by the sentient being to which the symbiote is attached.', NULL, NULL, 'Finds and removes a symbiotic organism, including Splugorth Bio-Wizardry symbiotes, over one hour with minimal injury to the host. Prior damage from the symbiote remains, scarring is almost certain, and all bonuses, benefits and powers it gave are lost. Usually neither host nor symbiote suffers, but sometimes removal kills the symbiote and/or permanently harms the host; unwanted removals are often painful. The caster must watch the whole process, as organisms retreat back into the host if the spell is left unfinished.', NULL, 'biomancy', NULL),
  ('Biomancy: Forest Walk', 12, 195, '195; +20 to sort the plants by type', NULL, 'import', 'Rifts World Book 32: Lemuria p.106', 'rifts', NULL, 'The plants can walk for 10 minutes per level of experience.', NULL, 'None, unless the plants are magical or sentient creatures, in which case they may make a standard saving throw of 12 or greater vs magic. Millennium Trees and other such powerful plant beings are immune.', '40 foot (12.2 m) radius per level of experience.', NULL, 'Every plant in the area, from grass to the tallest trees, uproots itself and walks to a place the caster chooses. Used to transplant vegetation, reach the rock beneath, plant farms and orchards, landscape, clear land, replant burned areas, or disguise camps and entrances. The walking plants cannot attack and remain S.D.C. structures vulnerable to fire and M.D. weapons. For 20 more P.P.E. the caster can sort the plants by species and send each kind to its own location.', NULL, 'biomancy', NULL),
  ('Biomancy: Mimic Animal or Plant', 12, 500, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.106', 'rifts', 'Self.', '15 minutes per level of experience.', NULL, 'Standard if the person does not wish to be transformed.', NULL, NULL, 'The caster lays a hand on an animal or plant and then transforms into it: either an exact copy of that individual (down to birthmarks, fingerprints and genetic markers) or a generic member of its species with all racial abilities, powers and physical attributes. His own mind, memories, personality, skills and mental attributes are unchanged. Works on any living thing whose blueprint is DNA.', NULL, 'biomancy', NULL),
  ('Biomancy: Reconstruction', 12, 675, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.106', 'rifts', 'Self or other by touch. Can be performed on sentient beings, animals and plants.', 'Permanent.', NULL, 'None, unless the person does not want to be healed, or have something removed/restored, in which case they are +7 to save.', NULL, NULL, 'Rebuilds the subject''s body to its natural state from its own DNA. Removes magic and ordinary tattoos, parasites, symbiotes, M.O.M. implants, cybernetics and bionics (a full conversion borg regrows a whole body), Bio-Wizard and Juicer augmentation and chemical damage, and regrows missing limbs; the caster may remove one, some or all of these. Juicers are restored without addiction; Crazies keep only half their insanities but lose the implants'' powers, bonuses and psionics. Also heals combat, burn, poison and chemical damage without scars and restores full Hit Points, S.D.C. or M.D.C. Does not affect emotions, memories, insanity or curses, and cannot change genetic defects, mutations or the genetic code.', NULL, 'biomancy', NULL),
  ('Ocean: Buoyancy Blast', 3, 9, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.108', 'rifts', 'By touch or can be cast 20 feet (6.1 m) away per level of experience.', 'Five minutes per level of experience on inanimate objects, two minutes per level on the living.', NULL, 'None for inanimate objects, standard for surface dwellers, +2 to save for aquatic/amphibious people, +3 to save for fish, crustaceans, cetaceans, and other aquatic animals.', NULL, NULL, 'Makes one person, animal or object buoyant so it rises toward the surface; weight limit 200 lbs +50 lbs per caster level, so it fails on boats, subs and most Bio-Armor or power armor wearers. Handheld weapons affected underwater are -2 to strike and float off if released. A person who fails to save drifts upward; resisting by swimming costs half his melee attacks, -4 Perception, no initiative, -2 on all combat rolls, -20% skills at double time, and half Spd unless moving up. Holding onto something halves the effect and penalties. Against a fast target (40 mph or more, such as a torpedo, harpoon or spear) the caster must roll 16+ to strike; a hit veers it upward 1D4x10 degrees off course, a miss wastes the spell.', NULL, 'ocean', NULL),
  ('Ocean: Capture Moisture', 1, 3, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.108', 'rifts', 'Self.', 'One minute per level of experience, with permanent results.', NULL, 'None', NULL, NULL, 'Gathers water out of dew, rain droplets on leaves, fog and humidity. The caster can fill a container or direct the water onto a plant, tree or patch of crops 5 feet in diameter per level. Yield is up to one gallon (3.7 liters) per caster level per minute, doubled in the 15 minutes following a rain shower or the 30 minutes following a thunderstorm. The water is fit to drink and to water crops.', NULL, 'ocean', NULL),
  ('Ocean: Current Curtain', 9, 45, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.108-109', 'rifts', '20 foot (6.1 m) diameter sphere of influence per level of experience, and can be cast up to 100 feet (30.5 m) away per level of experience.', 'One minute per level of experience.', NULL, 'None. Must fight the current to break free or be pulled out, otherwise the victim is trapped within for the duration of the spell or until the spell caster cancels its effect.', NULL, NULL, 'Creates either a sphere of calm water untouched by surrounding currents and waves, or a sphere of violent turbulence. Animals, people, small boats and mini-subs entering the turbulent sphere are trapped; swimming out needs Robot P.S. 40 or Supernatural P.S. 26 and takes 1D4 melee rounds. Those trapped lose 1D4 attacks per melee round, are -5 to strike at long range, have other combat bonuses halved, are -30% on skills, and lose handheld items not gripped tightly. Torpedoes and projectiles hitting it are slowed 30% and pushed 1D4x10% off course (smart bombs can correct after exiting). Ships, submarines and sea monsters only suffer shaking, loss of sonar and communications while inside, and 2D6% less speed.', NULL, 'ocean', NULL),
  ('Ocean: Depth Tolerance', 2, 6, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.109', 'rifts', 'Self or one other by touch.', '30 minutes per level of experience.', NULL, 'Standard.', NULL, NULL, 'A lesser form of Impervious to Ocean Depths. The recipient can safely descend to 50% deeper than is normal for his species (600 feet is given as the human norm) or to one mile (1.6 km), whichever figure is greater; for a human that is one mile. It does not allow travel to trench bottoms or abyssal plains. One individual per casting, and the subject is in grave danger if it expires while he is deep.', NULL, 'ocean', NULL),
  ('Ocean: Draw Water', 5, 15, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.109', 'rifts', '100 feet (30.5 m) per level of experience.', 'One minute per level of experience.', '6D6 to vampires per melee attack (3D6 to a vampire punching through the water wall)', 'None for the water; -2 to dodge for those targeted for a soaking.', NULL, NULL, 'Pulls nearby water up and around the caster. It can be thrown to soak a target, douse a shipboard fire or wash away debris; against vampires each soaking does 6D6 damage and uses two attacks (one to draw, one to direct). Alternatively the water hangs around the caster to hide his features (only his outline shows), wash things, or form a ring wall around him that holds back biting insects, small animals or fire; a vampire punching through it takes 3D6 damage, none if using a melee weapon. It can also simply raise water from a well or sunken source for drinking or filling containers.', NULL, 'ocean', NULL),
  ('Ocean: Light up the Deep', 5, 15, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.109', 'rifts', 'Lights up a 50 foot (15.2 m) diameter per level of experience and can be cast up to 200 feet (61 m) away per level of experience. Cannot be cast on land; underwater only.', 'One minute per level of experience.', NULL, 'Standard.', NULL, NULL, 'Summons a brilliant yellow-white sphere approximating sunlight, underwater only. Creatures adapted to deep-sea darkness flee (roll vs Horror Factor 15); any that remain are blinded for the duration. Aquatic undead take no damage but are driven outside the lit radius. Beings able to see in light need 1D4 melee rounds to adjust, losing one melee attack and suffering -5 on Perception and all combat rolls meanwhile. No special effect in water that is already lit. Also useful for searching, reading and signalling.', NULL, 'ocean', NULL),
  ('Ocean: Manipulate Thermoclines', 6, 24, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.109', 'rifts', 'Affects a one mile (1.6 km) radius per level of experience.', '5 minutes per level of experience.', NULL, 'None', NULL, NULL, 'Shifts a thermocline (a horizontal temperature boundary layer in a large body of water) so it lies above or below a target. The target''s sonar and scent tracking are then confined to its own layer, leaving it blind to sensor readings and scents from beyond the boundary. The layer is no physical barrier and anything that swims can cross it. Thermoclines stay horizontal, parallel to the surface; they cannot be made vertical or wrapped around an object.', NULL, 'ocean', NULL),
  ('Ocean: Water Shield', 7, 20, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.109-110', 'rifts', 'Self or another person or object by touch or 10 feet (3 m) away; line of sight required.', 'One minute per level of experience to remain dry. Instant drying.', NULL, 'None', NULL, NULL, 'Cast before exposure, an invisible aura keeps the recipient completely dry and unharmed by water; vampires, other water-vulnerable creatures, paper and electronics can cross rivers, swim or dive safely. Used the other way, it instantly dries a wet person or object, but water damage already done stays: food is ruined, electronics have only a 01-45% chance to work, paper and books stay warped (a book swells to triple thickness), and a dried gun has a 01-90% chance to work with fresh ammunition. Only surfaces, skin and worn apparel are dried; it does not desiccate fish or fruit and has no effect on water beings.', NULL, 'ocean', NULL);

INSERT OR IGNORE INTO skills (name, category, base, base_formula, per_level, systems, source, source_book, note, bonuses, level_bonuses) VALUES
  ('Horsemanship: Aquatic Animals', 'Horsemanship', 40, NULL, 4, '["rifts"]', 'import', 'Rifts World Book 32: Lemuria p.55', '40%/20%+4%; +20% on a cetacean that is willing to carry riders. Works like Horsemanship: General, but for large aquatic mounts (giant manta rays, giant stingrays, sea turtles and similar beasts, Earthly, otherworldly or Biomancy-made). Also covers riding dolphins and whales, which are intelligent and can be ridden only when they agree.', NULL, NULL),
  ('Horsemanship: Sea Monsters', 'Horsemanship', 30, NULL, 4, '["rifts"]', 'import', 'Rifts World Book 32: Lemuria p.55', '30%/20%+4%; +20% if the monster is intelligent and willing to carry riders. Works like Horsemanship: Exotic Animals, but for large to massive aquatic monsters and sea serpents (Earthly, otherworldly or Biomancy-made). Also covers sea dragons, other dragons and sentient monsters that agree to be ridden.', NULL, NULL),
  ('Horsemanship: Serpent Hunter', 'Horsemanship', 70, NULL, 3, '["rifts"]', 'import', 'Rifts World Book 32: Lemuria p.55', '70%/50%+3%; +10% if the mount is intelligent or a serpent and is willing to carry the Serpent Hunter. Works like Horsemanship: Cyber-Knight, but applies to any large aquatic animal, sea monster or sea serpent.', NULL, NULL),
  ('Language: Cetacean', 'Technical', 30, NULL, 4, NULL, 'import', 'Rifts World Book 32: Lemuria p.55', '30%+4% as an additional language; 86%+1% per level as a native language (includes Lemurians and Merans). The ultrasonic language of dolphins, whales and pneuma-biforms, treated as one common tongue. Requires the ability to hear and make ultrasonic sound (Lemurians, Merans, or cyborgs with the Ultra Ear and Inaudible Frequency Transmission implants); impossible otherwise. Gives +5% to learn Ichthylean/Milu.', NULL, NULL),
  ('Language: Ichthylean/Milu', 'Technical', 15, NULL, 2, NULL, 'import', 'Rifts World Book 32: Lemuria p.55', '15%+2% as an additional language; 88%+1% per level for Ichthyleans. The chemical/gurgling language of the Ichthyleans (clicks, chirps, thumps, body language and chemical exchanges), which so far only Ichthyleans can truly speak; they deal with other races by Empathy and Telepathy instead. Language: Cetacean gives +5% to learn it.', NULL, NULL),
  ('Language: Lemurian', 'Technical', 50, NULL, 5, NULL, 'import', 'Rifts World Book 32: Lemuria p.55', '50%+5% as an additional language for non-Lemurians; 88%+1% per level for native Lemurian speakers, who are -20% to speak other dialects and forms of Polynesian. An ancient form of Polynesian. Speakers get +10% when they also take Language: Oceanic.', NULL, NULL),
  ('Language: Oceanic', 'Technical', 50, NULL, 5, NULL, 'import', 'Rifts World Book 32: Lemuria p.55', '50%+5% as an additional language; 88%+1% per level for native speakers. A blend of Thai, Malaysian, Indonesian, Vietnamese, Chinese and Polynesian, much as Euro is a blend. Those who speak Lemurian get +10% when they take this skill as well.', NULL, NULL),
  ('Lore: Sea Creatures', 'Technical', 25, NULL, 5, '["rifts"]', 'import', 'Rifts World Book 32: Lemuria p.55', 'General and practical knowledge of the sea and its life (seaweed, reefs, crustaceans, fish, aquatic mammals) plus stories and legends of sea monsters, sea serpents, Lemurians, Merans, Milu, the Lord of the Deep and his minions, and the New Navy. Includes beach and lagoon hazards, poisonous and stinging sea life, first aid for stings, and what to do around sharks.', NULL, NULL),
  ('Hand to Hand: Demon Combat', 'Physical', 0, NULL, 0, '["rifts"]', 'import', 'Rifts World Book 32: Lemuria p.56-58', 'Kapu Kuialua (also Pa Kuialua, Lua, Lemurian Demon Combat), a Mauian Order martial art. Requires at least 16 P.P.E. and dedication to martial combat; a Lemurian secret seldom taught to outsiders. Among Lemurians: Oceanic Guardsmen (60%), Serpent Hunters (36%), select Mauian Order members (2%), others (2%). Biomancers never learn it; a mage who does halves his own P.P.E., O.C.C. bonuses and starting spells, and halves this skill''s bonuses. After one full melee round of focus and 13 P.P.E. (own or ambient), bare-handed punch and kick damage, including P.S. and skill damage bonuses, is Mega-Damage against supernatural beings and creatures of magic only (not man-made M.D.C. armor, structures or D-Bees; S.D.C./Hit Point damage to mortals) for one minute per level, double at a ley line, stone pyramid or Lemurian ziggurat, quadruple at a nexus. A being that already does M.D. adds 50%. Can parry M.D. attacks of opponents under 10 feet tall. Does not apply to handheld weapons. Without the P.P.E. the bonuses remain but damage is S.D.C. In S.D.C. settings: double damage to the supernatural, and a Critical Strike goes direct to Hit Points. ''Demon'' means any supernatural being.', NULL, '[{"level":1,"combat":{"attacks_base":4,"roll":1,"pull_punch":2},"note":"Body flip/throw, body block/tackle, holds, roll with impact, pull punch, disarm, punch (1D4), knee and elbow strikes (1D6), kick attack (2D4), plus the usual strike, parry and dodge. +1 on Perception Rolls and +1 to save vs Horror Factor."},{"level":2,"combat":{"initiative":1,"strike":1},"note":"Snap kick (1D6) and knife hand (2D4). +2 to save vs Seduction."},{"level":3,"combat":{"disarm":1},"note":"+1 to entangle and +1 to save vs Horror Factor. The book repeats snap kick (1D6) and knife hand (2D4) here. +2 to save vs demonic possession (not psionic attacks)."},{"level":4,"combat":{"attacks":1,"parry":1},"note":"Karate kick (2D6). +3 to save vs insanity and magic-based illness."},{"level":5,"combat":{"strike":1,"disarm":1},"note":"+1 to save vs Horror Factor. +2 to punch and kick damage, and +1D6+1 to the character''s base P.P.E. +2 to save vs demonic mind control and +5% to save vs coma and death."},{"level":6,"combat":{"dodge":1},"note":"Critical Strike on a natural 18-20, and on attacks made from behind. Palm strike (2D6). +2 to save vs attacks directed at the soul."},{"level":7,"combat":{"strike":1},"note":"Paired weapons. +1 to save vs Horror Factor. Stone fist strike (3D6). Stone hands: can grapple, hold or parry beings and weapons made of or covered in fire or energy."},{"level":8,"combat":{"attacks":1,"disarm":1},"note":"Palm strike (2D4+2). Impervious to demon fire, heat blasts and lava attacks and to dragon fire breath; magic fire from spells and magic weapons, and man-made weapons, still do full damage."},{"level":9,"combat":{"initiative":1,"strike":1},"note":"+1 to save vs Horror Factor. +3 to punch and kick damage, and +2D6+2 to the character''s base P.P.E. +3 to save vs curses, +2 to save vs dark magic (Demon Magic, Necromancy, Soulmancy, and magic that changes alignment, corrupts, compels or controls)."},{"level":10,"combat":{"pull_punch":2},"note":"+1 to Perception Rolls. Stun Kick to head or spine: 3D6 damage, and on a natural 15 or better to strike the supernatural opponent''s bonuses and remaining attacks are halved for that melee round. +2 to save vs all forms of possession (including psionic) and insanity."},{"level":11,"combat":{"strike":1},"note":"+1 to entangle and +1 to save vs Horror Factor. Lightning Kick: two kicks of 2D6 each (4D6 total) as one melee attack; on a natural 19 or 20 the victim is stunned and loses 1D4 attacks that round. Impervious to demonic petrification."},{"level":12,"combat":{"pull_punch":1},"note":"+2 to body flip/throw. Double damage to the undead (vampires, zombies, animated dead). Breathe Without Air (as the third level spell) and impervious to vampire mind control and to Trance magic and psionic attacks."},{"level":13,"note":"Death Blow (see the core rule book): triple damage on a natural 20, and the creature cannot bio-regenerate that damage for 1D4 hours. +1 to save vs Horror Factor. Double damage to Lesser Demons. +3 to save vs illusion magic and Seduction; impervious to demonic cold attacks."},{"level":14,"combat":{"attacks":1,"strike":1},"note":"Double damage to Greater Demons. Can erect a light magical force field (like Armor of Ithan) with 1D4+3 M.D.C. per level for 6 P.P.E.; lasts five minutes or until depleted."},{"level":15,"combat":{"initiative":1},"note":"Critical Strike on a natural 17-20. +1 to save vs Horror Factor. Triple damage to the undead; can hit ghosts/Entities, Astral Beings and other ethereal and energy beings for normal punch and kick damage (no damage bonuses). Impervious to possession and +15% to save vs coma/death."}]'),
  ('Symbiotic Conduit Vehicle Combat', 'Pilot', 60, NULL, 2, '["rifts"]', 'import', 'Rifts World Book 32: Lemuria p.58', '60%+2% (plus any O.C.C. bonus). For Lemurian combat vehicles powered and steered through a Symbiotic Conduit organism; nearly anyone can pilot one, but trained Lemurian warriors get: +1 on initiative, +2 to strike with the vehicle''s weapon systems, +2 to dodge, half the usual penalty for evasive maneuvers, stunt flying and crash landings, and +1 attack per melee round at levels 2, 4, 8 and 12. These add to the pilot''s own hand to hand and attribute bonuses and apply only while in the vehicle.', NULL, NULL);

INSERT OR IGNORE INTO psionic_powers (name, category, isp, isp_note, variant_note, source, source_book, system, range, duration, saving_throw, description, min_tier) VALUES
  ('Hold Breath', 'Special', 2, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.82', NULL, 'Self.', 'Ten minutes +1 minute per level of experience.', NULL, 'A Hydro-Psionic of the Spouter, and one of the three every Spouter starts with. A kind of Bio-Manipulation: the psychic fills his lungs to their limit and cuts his body''s oxygen use so he can hold his breath for the whole duration. Suited to short dives in lakes, rivers and seas.', NULL),
  ('Hydro-Ice Skate', 'Special', 3, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.83', NULL, 'Self.', 'Five minutes per level of experience.', NULL, 'A Hydro-Psionic of the Spouter. He can walk, slide or skate over any ice-covered surface, in footwear or barefoot, at three times his running speed, and will not break through even the thinnest ice. Limitation: the ice must already exist, and he can only follow where the ice goes.', NULL),
  ('Hydroplane Skating', 'Special', 5, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.83', NULL, 'Self.', 'Three minutes per level of experience; double when raining.', NULL, 'A Hydro-Psionic of the Spouter. Draws a thin film of water from an existing source up to 1,000 feet (305 m) away (rain, dew, a pool, pipes, a sink, a pond or lake) into a path that stays just ahead of him, and he skates on it at twice his running speed. The path must be fairly level but can climb slopes of up to 45 degrees and go up and over parked vehicles or debris whose low starting point is no higher than two feet (0.6 m). It cannot go straight up fences, walls or buildings, nor upside down. Water must be available.', NULL),
  ('Hydro-Propulsion', 'Special', 7, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.83', NULL, 'Self.', 'Five minutes per level of experience.', NULL, 'A Hydro-Psionic of the Spouter, and one of the three every Spouter starts with. Moves him on or under water at 5 mph (8 km) per level of experience: underwater he shoots forward like a torpedo, and on the surface he rides as if on an unseen surfboard. He steers by thought, but only in sharp turns and never sideways; each change of direction costs one melee attack/action. Travelling in a circle halves speed and uses all but one attack/action that round. Needs a body of water big and deep enough to swim in.', NULL),
  ('Psychic Purification: Liquid', 'Special', 7, '7; double (14) to desalinate salt water', NULL, 'import', 'Rifts World Book 32: Lemuria p.83', NULL, 'Touch.', 'Permanent results in one melee round.', NULL, 'A Hydro-Psionic of the Spouter. With his hands on a container of water or another drinkable liquid (milk, broth, juice, wine), he purifies up to half a gallon (1.9 liters) per level of experience for human consumption, killing all dangerous bacteria, parasites and germs. It takes one full melee round (15 seconds). For twice the I.S.P. he can instead turn salt water into drinkable, desalinated water.', NULL),
  ('Resist Dehydration', 'Special', 4, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.83', NULL, 'Self.', '2 hours when on the move; six when sitting still and meditating.', NULL, 'A Hydro-Psionic of the Spouter. A mind over matter discipline. While active he dehydrates at half the normal rate, but must keep to a slow pace: half Spd, and in combat -2 on initiative and -2 attacks per melee round. Sitting still in meditation, even under a blazing sun, dehydration falls to 10% of normal; he still feels very thirsty and will sunburn unless covered, though the sunburn is halved.', NULL),
  ('Sense Water', 'Special', 2, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.83', NULL, 'Self; a radius of 1,000 feet (305 m) +100 feet (30.5 m) per level of experience.', '2 minutes per level of experience.', NULL, 'A Hydro-Psionic of the Spouter, and one of the three every Spouter starts with. He senses the presence and general location of water sources inside the radius, natural (pond, swamp, river, sea, underground spring) or man-made (pool, bathtub, tank, drain, sewer, reservoir). He also learns whether the water is pure and drinkable, impure but drinkable, or foul and unsafe, whether it is fresh or sea water, and whether it carries dangerous parasites or disease.', NULL),
  ('Water Breakout', 'Special', 2, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.83-84', NULL, '15 feet (4.6 m) per level of experience; line of sight required.', 'Instant result.', 'To avoid being sprayed, dodge at -2.', 'A Hydro-Psionic of the Spouter. Makes a sealed container of water or another thin liquid (soda, coffee, juice, milk, alcohol, cleaning solution) burst out in a spray hitting everyone in a four foot (1.2 m) diameter, or makes a faucet gush for one second. No effect on open containers, petroleum products or thick mixtures (mud, stew, paint, paste). Everyone within a 10 foot (3 m) radius is -2 on Perception Rolls and -2 on initiative and pauses or moves aside; those splashed take double those penalties and lose one melee attack/action. Hot, caustic or stinging liquid in the eyes: no Perception Rolls, loss of initiative and two melee attacks, and blind (-10 on all combat rolls) until washed out; with hot water the penalties last 1D6+1 melee rounds. Can also supply water for his other powers.', NULL),
  ('Water Levitation', 'Special', 8, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.84', NULL, 'The Spouter or another person weighing up to 200 pounds (90 kg), raised 10 feet (3 m) per level of experience; water can be drawn from a source up to 100 feet (30.5 m) away per level of experience.', '3 minutes per level of the psychic.', NULL, 'A Hydro-Psionic of the Spouter. Lifts himself or one other person of up to 200 pounds (90 kg) on a column of water, straight up only, to 10 feet (3 m) per level of experience. The column can rise out of a body of water, or the water can be drawn across land from an existing source (rain, pool, pipes, drain, sink, pond, lake) up to 100 feet (30.5 m) away per level and then made to rise. Water must be available.', NULL),
  ('Water Telekinesis', 'Special', 3, '12 to flow water; to throw: 3 small, 5 medium, 5 large', NULL, 'import', 'Rifts World Book 32: Lemuria p.84', NULL, 'Throw/Hurl Water: 60 feet (18.3 m); double underwater. Flow Water: 100 feet (30.5 m) per level of experience; double underwater.', 'Two minutes per level of experience.', 'Dodge with a penalty of -2.', 'A Hydro-Psionic of the Spouter. Telekinesis that works only on water and watery liquids from an available, clearly visible source in range; each feat uses one melee attack. Flow (12 I.S.P., unlimited amount while the source lasts): water runs backward, up walls, across ceilings, in shapes or written words, at 50 feet (15.2 m) per melee round; he can also halt or divert a flow, hold a faucet shut, or draw water slowly from a closed tap or open container. Throw (3 I.S.P. for up to half a gallon/1.9 liters, 5 for up to one gallon/3.8 liters, 5 for 5 gallons/19 liters per level): a pulse merely soaks the target (3D6 to vampires); a blast does 1 S.D.C. small, 1D4 medium, 2D4 large (never more than 2D4). A large blast does 5D6 to vampires; lesser amounts do them double damage.', NULL),
  ('Water Telekinesis Attack (M.D.)', 'Special', 10, '10 for S.D.C. damage, 20 for Mega-Damage', NULL, 'import', 'Rifts World Book 32: Lemuria p.84', NULL, '30 feet (9.1 m) +10 feet (3 m) per level of experience. Double range underwater.', 'Instant.', 'Dodge or parry; -2 underwater.', 'A Hydro-Psionic of the Spouter. Pulls a spinning vortex of water out of a nearby body of water and drives it into one opponent like a sledgehammer. Damage is 1D6x10 S.D.C. for 10 I.S.P. or 2D6+2 M.D. for 20 I.S.P. Vampires lose 2D6x10 or 4D6x10 Hit Points respectively, and other creatures vulnerable to water take double damage.', NULL),
  ('Water Telekinesis Bolt (S.D.C.)', 'Special', 6, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.84', NULL, '10 feet (3 m) per level of experience. Double range underwater.', 'Instant.', 'Dodge or parry, -2 underwater.', 'A Hydro-Psionic of the Spouter. Draws a small spinning vortex of water from a nearby body of water and shoots it at one opponent for 3D6 S.D.C. Vampires and other creatures vulnerable to water take double damage.', NULL),
  ('Water Telekinesis Punch', 'Special', 7, '7 underwater; 21 on dry land', NULL, 'import', 'Rifts World Book 32: Lemuria p.84', NULL, 'Touch or one foot (0.3 m) per level of experience.', 'One melee round; each punch counts as one melee attack.', 'Dodge or parry, -2 underwater.', 'A Hydro-Psionic of the Spouter. Wraps his fist in a small spinning vortex of water taken from a nearby body of water; each punch does 2D6 S.D.C./Hit Point damage plus his P.S. damage bonus, if any. Vampires and other creatures vulnerable to water take double damage. Costs 7 I.S.P. underwater and 21 on dry land, where water must still be close by.', NULL),
  ('Water Telekinesis Rain', 'Special', 5, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.84-85', NULL, '10 foot (3 m) diameter per level of experience around the psychic, or up to 30 feet (9.1 m) away from him per level of experience.', 'One melee round per level of experience.', NULL, 'A Hydro-Psionic of the Spouter. Lifts water droplets into the air and lets them fall over the area as the equivalent of a light rain. Useful for wetting an area, watering crops, putting out small fires and showering. Exposed vampires take 1D4 Hit Points per melee round. Enough water must be on hand.', NULL),
  ('Water Walk Telekinesis', 'Special', 6, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.85', NULL, 'Self.', 'Five minutes per level of experience.', NULL, 'A Hydro-Psionic of the Spouter. Raises the water''s surface tension so he can walk on it, or ride the waves like an unseen raft. He moves at his normal walking/running speed, or at the speed and in the direction of the waves when riding them, never faster. Going against the tide, into the waves or across them is done at one quarter of normal walking speed. Enough water must be on hand.', NULL),
  ('Hydro-Magnet', 'Special', 10, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.85', NULL, 'Self.', 'Three minutes per level of experience.', NULL, 'A Hydro-Super-Psionic of the Spouter. Water within a 50 foot (15.2 m) radius per level of experience flows to him and keeps coming, up to 100 gallons (378 liters) per level each melee round, soaking a 20 foot (6.1 m) diameter around him. A room or vehicle that is not watertight begins to fill, and a boat may be put at risk of sinking depending on its size. Mostly used to cause panic, drive people off or douse a fire; in the right setting it can drown people, and it chases vampires away. Water must be available.', NULL),
  ('Hydration', 'Special', 15, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.85', NULL, 'Self, or one other by touch.', 'Instant results.', NULL, 'A Hydro-Super-Psionic of the Spouter. A bio-feedback discipline that brings a dehydrated subject back to healthy hydration in 1D6+1 minutes, removing every dehydration penalty and impairment and restoring 2D6+11 Hit Points (or 2D4 M.D.C.) when that period ends. The subject must be in a bath of water or wrapped in soaking wet blankets. To treat someone else the Spouter keeps his hands on them and meditates for the whole period. Water must be available.', NULL),
  ('Water Breathing', 'Special', 8, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.85', NULL, 'Self.', '10 minutes per level of experience.', NULL, 'A Hydro-Super-Psionic of the Spouter. He takes oxygen straight from the water around him, is fully at ease in any water environment, and can withstand depths 25% greater than normal.', NULL),
  ('Water Pressure Endurance', 'Special', 12, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.85', NULL, 'Self.', '10 minutes per level of experience.', NULL, 'A Hydro-Super-Psionic of the Spouter. With no protective gear he survives at twice his normal depth tolerance. Living Bio-Armor or symbiotes he wears are affected too, and can go (with him inside) 30% deeper than their normal capacity.', NULL),
  ('Water Shield', 'Special', 30, NULL, NULL, 'import', 'Rifts World Book 32: Lemuria p.85', NULL, 'Self or up to a distance of 40 feet (12.2 m) per level of experience within line of sight.', '10 minutes per level of experience on the surface of water, on dry land, or underwater.', '-5 to dodge.', 'A Hydro-Super-Psionic of the Spouter. In effect a Telekinetic Force Field made of water (full rules in Rifts Ultimate Edition). The shield has 25 M.D.C. per level of experience when made on dry land or on the water''s surface, 35 M.D.C. per level when made underwater. It soaks up attacks like a force field; heat, fire and plasma do only half damage to it, and a vampire touching it takes 3D6 damage. Made on the surface it stays on the surface; made underwater it hangs at that depth but drifts with the tide. Needs at least 10,000 gallons (37,850 liters) of water within 100 feet (30.5 m) of the Spouter.', NULL),
  ('Wave Attack', 'Special', 10, '10 for S.D.C. damage, 20 for M.D.', NULL, 'import', 'Rifts World Book 32: Lemuria p.85-86', NULL, '50 feet (15.2 m) per level of experience.', 'Instant.', '-3 to dodge.', 'A Hydro-Super-Psionic of the Spouter. Raises a wave six feet (1.8 m) tall per level of experience, up to 12 feet (3.6 m) wide, that slaps into the target; it counts as two attacks and needs water. Knockdown wave (10 I.S.P.): 4D6 S.D.C., victim loses 1D4 melee attacks, initiative and Perception and is carried 2D4 yards; M.D. beings and robots under two tons are also knocked down. Damaging wave (20 I.S.P.): 5D6 M.D., loses 1D4+1 attacks, initiative and Perception, carried 3D6 yards; M.D. beings, robots and vehicles under four tons are knocked down. The Spouter may ride the wave unharmed to follow up; for the 3-4 seconds it takes he can be hit only by a Called Shot at -3 to strike. He cannot ride one into a wall or cliff (he would take double damage).', NULL);

